# clean_data.py – data cleaning pipeline
"""
Purpose
-------
* Load raw CSV files generated by ``generate_synthetic_data.py``.
* Perform a quick exploratory data check (shape, dtypes, nulls, duplicates).
* Fix obvious data‑type issues (e.g., dates as strings → ``datetime``).
* Handle missing values – the synthetic data is already complete, but the code is defensive.
* Remove duplicate rows.
* Standardise textual columns (strip whitespace, lower‑case where appropriate).
* Write the cleaned tables to ``data/processed/`` for downstream steps.
"""

import os
import pandas as pd
from pathlib import Path

RAW_DIR = Path(__file__).resolve().parents[1] / "data" / "raw"
PROC_DIR = Path(__file__).resolve().parents[1] / "data" / "processed"

os.makedirs(PROC_DIR, exist_ok=True)

def inspect(df: pd.DataFrame, name: str) -> None:
    print(f"--- {name} ---")
    print("Shape:", df.shape)
    print("Dtypes:\n", df.dtypes)
    print("Nulls:\n", df.isnull().sum())
    dup = df.duplicated().sum()
    print(f"Duplicate rows: {dup}\n")

def clean_customers(df: pd.DataFrame) -> pd.DataFrame:
    # Convert ids to string (already strings in synthetic data)
    df["customer_id"] = df["customer_id"].astype(str)
    # Standardise text columns
    for col in ["customer_name", "customer_email", "city", "state"]:
        if col in df.columns:
            df[col] = df[col].str.strip().str.lower()
    return df

def clean_products(df: pd.DataFrame) -> pd.DataFrame:
    df["product_id"] = df["product_id"].astype(str)
    df["category"] = df["category"].str.strip().str.lower()
    return df

def clean_orders(df: pd.DataFrame) -> pd.DataFrame:
    df["order_id"] = df["order_id"].astype(str)
    # Parse dates
    df["order_date"] = pd.to_datetime(df["order_date"], errors="coerce")
    df["delivery_date"] = pd.to_datetime(df["delivery_date"], errors="coerce")
    df["order_status"] = df["order_status"].str.lower()
    return df

def clean_order_items(df: pd.DataFrame) -> pd.DataFrame:
    df["order_id"] = df["order_id"].astype(str)
    df["product_id"] = df["product_id"].astype(str)
    return df

def clean_payments(df: pd.DataFrame) -> pd.DataFrame:
    df["order_id"] = df["order_id"].astype(str)
    df["payment_timestamp"] = pd.to_datetime(df["payment_timestamp"], errors="coerce")
    return df

def clean_reviews(df: pd.DataFrame) -> pd.DataFrame:
    df["order_id"] = df["order_id"].astype(str)
    df["review_timestamp"] = pd.to_datetime(df["review_timestamp"], errors="coerce")
    return df

def main():
    # Load raw tables
    customers = pd.read_csv(RAW_DIR / "customers.csv")
    products = pd.read_csv(RAW_DIR / "products.csv")
    orders = pd.read_csv(RAW_DIR / "orders.csv")
    order_items = pd.read_csv(RAW_DIR / "order_items.csv")
    payments = pd.read_csv(RAW_DIR / "payments.csv")
    reviews = pd.read_csv(RAW_DIR / "reviews.csv")

    # Inspect each table (prints to console – useful when running the script locally)
    for df, name in [(customers, "customers"), (products, "products"), (orders, "orders"),
                     (order_items, "order_items"), (payments, "payments"), (reviews, "reviews")]:
        inspect(df, name)

    # Clean
    customers = clean_customers(customers).drop_duplicates()
    products = clean_products(products).drop_duplicates()
    orders = clean_orders(orders).drop_duplicates()
    order_items = clean_order_items(order_items).drop_duplicates()
    payments = clean_payments(payments).drop_duplicates()
    reviews = clean_reviews(reviews).drop_duplicates()

    # Write cleaned files
    customers.to_csv(PROC_DIR / "customers_clean.csv", index=False)
    products.to_csv(PROC_DIR / "products_clean.csv", index=False)
    orders.to_csv(PROC_DIR / "orders_clean.csv", index=False)
    order_items.to_csv(PROC_DIR / "order_items_clean.csv", index=False)
    payments.to_csv(PROC_DIR / "payments_clean.csv", index=False)
    reviews.to_csv(PROC_DIR / "reviews_clean.csv", index=False)
    print("✅ Cleaned data saved to", PROC_DIR)

if __name__ == "__main__":
    main()
